<?php
namespace App\Http\Controllers;use Illuminate\Http\Request;use App\Models\{ZktecoDevice,ZktecoEmployeeMapping,ZktecoAttendanceEvent,Employee};use App\Services\ZKTeco\ZktecoService;
class ZktecoAdminController extends Controller{
 private function can(Request $r,string $p):void{abort_unless($r->user()->globalPermission($p),403);}
 public function status(Request $r){$u=$r->user();abort_unless($u->globalPermission('zktecoStatus')||$u->globalPermission('zktecoSyncActivity')||$u->globalPermission('zktecoUnmapped')||$u->globalPermission('zktecoRetry')||$u->globalPermission('zktecoReconciliation')||$u->globalPermission('zktecoErrors')||$u->globalPermission('zktecoDeviceDetails'),403);$data=[];if($u->globalPermission('zktecoStatus'))$data['devices']=ZktecoDevice::orderBy('name')->get(['id','name','status','last_seen_at','last_sync_at','active']);if($u->globalPermission('zktecoDeviceDetails'))$data['deviceDetails']=ZktecoDevice::orderBy('name')->get();if($u->globalPermission('zktecoUnmapped'))$data['unmappedCount']=ZktecoAttendanceEvent::where('processing_status','unmapped')->count();if($u->globalPermission('zktecoRetry'))$data['pendingCount']=ZktecoAttendanceEvent::where('processing_status','pending')->count();if($u->globalPermission('zktecoErrors'))$data['errorCount']=ZktecoAttendanceEvent::where('processing_status','error')->count();if($u->globalPermission('zktecoSyncActivity'))$data['lastEventAt']=ZktecoAttendanceEvent::max('received_at');return $this->ok($data);}
 public function events(Request $r){$u=$r->user();abort_unless($u->globalPermission('zktecoRawAudit')||$u->globalPermission('zktecoUnmapped')||$u->globalPermission('zktecoErrors')||$u->globalPermission('zktecoRetry'),403);$v=$r->validate(['status'=>'nullable|in:pending,processed,unmapped,error','deviceId'=>'nullable|string|max:190','employeeId'=>'nullable|string|max:190','perPage'=>'nullable|integer|between:1,100']);$q=ZktecoAttendanceEvent::orderByDesc('device_time');if(!$u->globalPermission('zktecoRawAudit')){$allowed=[];if($u->globalPermission('zktecoUnmapped'))$allowed[]='unmapped';if($u->globalPermission('zktecoErrors'))$allowed[]='error';if($u->globalPermission('zktecoRetry'))$allowed[]='pending';$q->whereIn('processing_status',$allowed);}if(!empty($v['status']))$q->where('processing_status',$v['status']);if(!empty($v['deviceId']))$q->where('device_id',$v['deviceId']);if(!empty($v['employeeId']))$q->where('employee_id',$v['employeeId']);return $this->ok($q->paginate($v['perPage']??50));}
 public function mappings(Request $r){$this->can($r,'zktecoMappings');return $this->ok(ZktecoEmployeeMapping::with(['device','employee'])->orderBy('device_id')->orderBy('enrollment_number')->get());}
 public function map(Request $r){$this->can($r,'zktecoMappingActions');$v=$r->validate(['deviceId'=>'required|string|max:190','employeeId'=>'required|string|max:190','enrollmentNumber'=>'required|string|max:100']);abort_unless(ZktecoDevice::whereKey($v['deviceId'])->exists()&&Employee::whereKey($v['employeeId'])->exists(),422,'Device or employee not found.');$conflict=ZktecoEmployeeMapping::where(['device_id'=>$v['deviceId'],'enrollment_number'=>$v['enrollmentNumber']])->where('employee_id','!=',$v['employeeId'])->exists();abort_if($conflict,422,'Enrollment number is already mapped on this device.');$m=ZktecoEmployeeMapping::updateOrCreate(['device_id'=>$v['deviceId'],'employee_id'=>$v['employeeId']],['enrollment_number'=>$v['enrollmentNumber'],'active'=>true]);return $this->ok($m,201);}
 public function replay(Request $r,string $id,ZktecoService $s){$this->can($r,'zktecoMappingActions');$e=ZktecoAttendanceEvent::findOrFail($id);$s->replay($e);return $this->ok($e->fresh());}
}
